'use strict';

const path = require('node:path');
const { TRACKED_MAJOR_MAP, javaCdsMajorFor, rangeSatisfiesTarget } = require('../constants');
const { majorFromRange } = require('./cds-version');
const { parsePomXml, getPomPropertyValue } = require('../util/pom');

function collectNode(ctx, cds) {
  const occurrences = [];
  for (const pkgPath of ctx.project.packageJsonFiles) {
    let pkg;
    try { pkg = JSON.parse(cds.utils.fs.readFileSync(pkgPath, 'utf8')); } catch { continue; }
    const deps = { ...pkg.dependencies, ...pkg.devDependencies };
    for (const name of Object.keys(TRACKED_MAJOR_MAP)) {
      const range = deps[name];
      if (!range) continue;
      const depMajor = majorFromRange(range);
      const map = TRACKED_MAJOR_MAP[name];
      const cdsMajor = map === null ? depMajor : (map[depMajor] ?? null);
      const permissive = rangeSatisfiesTarget(range, ctx.target);
      occurrences.push({ file: path.relative(cds.root, pkgPath), name, range, cdsMajor, permissive });
    }
  }
  return occurrences;
}

function collectJava(ctx, cds) {
  const occurrences = [];
  for (const pomPath of ctx.project.pomXmlFiles) {
    let pom;
    try { pom = parsePomXml(pomPath); } catch { continue; }
    const raw = getPomPropertyValue(pom, 'cds.services.version');
    if (!raw) continue;
    const m = raw.match(/^(\d+)/);
    if (!m) continue;
    const javaMajor = parseInt(m[1], 10);
    const cdsMajor = javaCdsMajorFor(javaMajor);
    occurrences.push({
      file: path.relative(cds.root, pomPath),
      name: 'cds.services.version',
      range: raw,
      cdsMajor,
      permissive: false,
    });
  }
  return occurrences;
}

function printListing(occurrences) {
  const { bold, error } = require('../../../lib/util/term');
  console.log(error('✗ Inconsistent cds versions detected'));
  console.log();
  const byFile = new Map();
  for (const o of occurrences) {
    if (!byFile.has(o.file)) byFile.set(o.file, []);
    byFile.get(o.file).push(o);
  }
  for (const [file, list] of byFile) {
    console.log(`  ${bold(file)}`);
    const nameCol = Math.max(...list.map(o => o.name.length));
    const rangeCol = Math.max(...list.map(o => String(o.range).length));
    for (const o of list) {
      const majorStr = o.cdsMajor === null ? '?' : `cds ${o.cdsMajor}`;
      console.log(`    ${o.name.padEnd(nameCol)}  ${String(o.range).padEnd(rangeCol)}  (${majorStr})`);
    }
  }
  console.log();
  console.log(`Please align the majors before running cds upgrade.`);
  console.log();
}

async function checkConsistency(ctx, cds) {
  const occurrences = [
    ...(ctx.project.isNode ? collectNode(ctx, cds) : []),
    ...(ctx.project.isJava ? collectJava(ctx, cds) : []),
  ];
  // Permissive ranges (e.g. `*`, `latest`, `>=7`) satisfy the target and
  // therefore contribute no evidence of a lagging major — skip them when
  // computing the majors set.
  const majors = new Set(
    occurrences
      .filter(o => !o.permissive && o.cdsMajor !== null)
      .map(o => o.cdsMajor)
  );
  const inconsistent = majors.size >= 2 && Math.min(...majors) < ctx.target - 1;

  if (inconsistent) {
    printListing(occurrences);
    return { ok: false, occurrences };
  }
  return { ok: true, occurrences };
}

module.exports = { checkConsistency };
